  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 13, 11, 8, 4, '{"niche_fit": "Skincare devices plus topical skincare \u2014 a strong fit for routine and results-content creators.", "ugc_evidence": "The brand actively recruits ambassadors on its own channels with application walkthroughs by creators; the program is built around creator links and codes.", "compensation": "The brand publishes a 15-25% commission range for ambassadors (its own Instagram), not a single rate, so commission_rate is null; no cap statement is published, so the cap is unknown.", "contact_access": "Open application on the brand''s own Superfiliate portal, linked from its social bios.", "opportunity_availability": "Program is open now with self-serve application and quick acceptance reported by creators.", "credibility": "Established beauty-tech brand with QVC and major retailer distribution."}'::jsonb);
