  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alpha-h.com/pages/affiliates', 'brand_program_page', 'affiliate_program_page', 'Alpha-H''s own Affiliates page (fetched 2026-11-21) runs two commission routes: ''Alpha Ambassadors'' for creators, influencers and brand ambassadors promoting on TikTok, Instagram, YouTube and Pinterest, and a Skincare Professionals route — both offering competitive commission rates, top-performer incentives, private affiliate offers and product seeding, with discount codes for the audience. The page publishes no percentage, no earnings-cap statement and no creator count, so cap and saturation are unknown.', 'verified', now());
