  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affilitizer.com/programs/ganni.com', 'Affiliate program tracker (Affilitizer)', 'affiliate_program', 'Fetched program page for ganni.com: the GANNI affiliate program is Active and exclusively available on Rakuten Advertising (Linkshare), Program ID 53873, live since May 2024, cookie 30 days, B2C in the Women''s Fashion category. It was removed from FlexOffers on June 5, 2026. The page carries no direct application link - publishers apply inside their Rakuten account - and Rakuten does not publish the commission rate, so commission_rate is null.', 'publicly_reported', now());
