  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.zennioptical.com/zenbassador-program', 'Brand''s own creator program page', 'creator_program', 'Fetched Zenni''s own Zenbassador page: the creator program has NO minimum follower requirement, is open to creators with public accounts in the US or Canada, and pays Zenni Gift Card rewards for posting plus a personal code that earns commission when shoppers use it, with access to new products and potential features. The same page links creators to the Commercial Program on Impact (app.impact.com).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/zenni-optical/', 'Affiliate program guide (Lasso)', 'affiliate_program', 'Fetched Lasso''s program page: the Zenni Optical affiliate program runs on Impact (join links point to app.impact.com) at 3% per sale with a 30-day cookie.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://whichprogram.is/articles/zenni-optical-affiliate-program-review', 'Program trackers (compareepc, WhichProgram)', 'rate_context', 'compareepc''s Impact program listing also records 3%, while WhichProgram describes a 3-10% range on Impact - the consistently listed base figure of 3% is recorded and the range is documented here. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
