  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.eyebuydirect.com/affiliate-program', 'Brand''s own affiliate page', 'affiliate_program', 'Fetched EyeBuyDirect''s own affiliate page: it advertises ''flexible commission up to 15%'' (a ceiling, not a base rate) and its Join now button routes to signup.cj.com, confirming the program runs on CJ Affiliate. The page states the brand was founded in 2006, joined the Essilor group in 2013, sells frames from $6, has an average purchase of $65 and a 48% repeat customer rate, and prints support@eyebuydirect.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-programs/eyebuydirect/', 'Program trackers (LinkClicky, commission.academy, compareepc)', 'affiliate_program', 'LinkClicky (''commission is officially listed''), commission.academy and compareepc consistently record the CJ program at 8% per sale; Lasso''s separate 3.2% figure belongs to a different network listing and is documented here rather than treated as a conflict. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
