  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/program/missoma', 'Rate aggregators (LinkApprove, Shopper.com)', 'rate_conflict', 'Rate deliberately left null: published figures conflict - 7% flat (BrandID), ''up to 10%'' (LinkApprove) and a 7-17% range on a sub-network listing (Shopper.com UK) - so no single verified rate can be recorded. Website tech trackers also show Rakuten and Awin tags on missoma.com, but Partnerize is the network named by the fetched program guide. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
