  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/jansport-affiliate-program/', 'Network program page (FlexOffers)', 'affiliate_program', 'Fetched FlexOffers program page confirms the JanSport affiliate program is live on FlexOffers with a 10-day cookie; the page describes JanSport as one of the most recognisable brands in outdoor gear and backpacks and explicitly invites publishers with a social media presence - but it publishes no numeric commission rate, so commission_rate is null. A secondary ''up to 10%'' figure on a rate roundup is a ceiling claim only. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'verified', now());
