  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile-terms/4329?setLocale=en_US.', 'https://ui.awin.com/merchant-profile-terms/4329?setLocale=en_US', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'lastminute.com affiliate programme on Awin', 'https://ui.awin.com/merchant-profile-terms/4329?setLocale=en_US', 'https://ui.awin.com/merchant-profile-terms/4329?setLocale=en_US', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile-terms/4329?setLocale=en_US', 'Network programme terms (Awin)', 'affiliate_program', 'Fetched Awin''s programme terms for lastminute.com (advertiser LMnext UK Ltd): standard commission is Flights 1%, Hotels 5%, Dynamic Packaging 3%, Lifestyle 3% and Gift Cards 1%, paid on the stay date, with a one-month pending period before commissions can be invoiced. The headline Hotels rate of 5% is recorded as commission_rate with the full category split documented here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/4363', 'Network programme profile (Awin, Ireland)', 'programme_profile', 'The Awin Ireland programme profile shows Hotels at 6% with a 28-day cookie and publishes the programme contact uk-lastminute@awin.com - a regional variant of the main programme''s 5% hotel rate, noted here rather than conflated. The brand also runs a separate ''One Year of Travel'' creator campaign that pays in travel vouchers, cited as creator evidence only, not as the affiliate rate. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 11, 9, 8, 5, '{"compensation": "Full category rates are published in Awin''s terms (Hotels 5%, packages 3%, flights 1%).", "contact_access": "A programme email is published on the Awin profile and application runs through Awin.", "credibility": "One of Europe''s best-known online travel agencies, operating since the late 1990s.", "niche_fit": "Pure travel product - flights, hotels and city breaks - squarely in the travel niche.", "opportunity_availability": "Open application to Awin publishers.", "ugc_evidence": "A creator campaign exists but pays in travel vouchers and is selective, so UGC evidence is modest."}'::jsonb);
