  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Virgin Atlantic affiliate programme on CJ Affiliate', 'https://www.virginatlantic.com/en-US/corporate/affiliates', 'https://www.virginatlantic.com/en-US/corporate/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.virginatlantic.com/en-US/corporate/affiliates', 'Brand''s own affiliates page', 'affiliate_program', 'Fetched Virgin Atlantic''s own affiliates page: the programme is run by Assembly Global on the CJ Affiliate platform, advertises ''earn up to 2% commission'' (a ceiling), a 30-day cookie and average order value of $1,700, excludes PPC and browser-extension affiliates, and publishes the programme contact VirginAtlantic-Affiliates@assemblyglobal.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/virgin-atlantic/', 'Program trackers (Lasso, AvidAffiliate)', 'rate_conflict', 'Rate deliberately left null: secondary sources conflict - Lasso records a flat 2% while AvidAffiliate''s CJ program data records 1.0% - and the brand''s own page states only an ''up to 2%'' ceiling, so no single verified base rate can be recorded. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 8, 12, 7, 5, '{"compensation": "Only an ''up to 2%'' ceiling is stated by the brand and trackers conflict, though the $1,700 average order value lifts per-sale value.", "contact_access": "A dedicated affiliate team email is published on the airline''s own page.", "credibility": "Flag-carrier-scale British airline founded in 1984.", "niche_fit": "A major long-haul airline is a core travel-niche advertiser.", "opportunity_availability": "Application via CJ with manual review; PPC and extension affiliates excluded.", "ugc_evidence": "Affiliate-only route; no creator-specific program was found."}'::jsonb);
