  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'American Tourister affiliate program on FlexOffers', 'https://www.affiliate-program.io/en/programs/american-tourister-flexoffers', 'https://www.affiliate-program.io/en/programs/american-tourister-flexoffers', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-program.io/en/programs/american-tourister-flexoffers', 'Network program data (FlexOffers via affiliate-program.io)', 'affiliate_program', 'Fetched FlexOffers program data for American Tourister: online-sale commission of 8.00% effective November 11, 2026 to February 1, 2027, a 14-day cookie and US targeting. The brand also appears on other networks (CJ at 8% per Lasso; an ''up to 8%'' Awin UK listing; Impact at 5% in older 2024 data) - FlexOffers is recorded as the current verified route with the multi-network picture documented here. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/24424', 'Network programme profile (Awin UK)', 'brand_background', 'Awin''s programme profile describes American Tourister as a brand with more than 85 years of heritage, the second-biggest luggage brand in the world with a presence in more than 90 countries - a Samsonite brand aimed at young, fashion-conscious travellers.', 'publicly_reported', now());
