  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cruisedirect.com/affiliates', 'Brand''s own affiliates page and FAQ', 'affiliate_program', 'Fetched CruiseDirect''s own affiliates page: affiliates earn 3% of the commissionable cruise fare with a 45-day cookie, and the page''s join link routes to the branded CJ Affiliate signup (cid 965192). The brand''s affiliate FAQ adds that the program is free to join, has NO traffic minimums, reviews applications within 24 hours, pays from a $25 threshold and pays 30 days after month end.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://jebcommerce.com/jebcommerce-welcomes-the-cruisedirect-affiliate-program/', 'Program manager announcement (JEBCommerce) and FMTC feed', 'program_management', 'JEBCommerce''s announcement confirms it manages the CruiseDirect program on CJ Affiliate and publishes the contact CruiseDirect@jebcommerce.com; FMTC''s merchant data independently records 3% commission, a 45-day cookie and $1,600 average order value. No source fetched states an earnings cap, so commission_cap is unknown; no absolute creator count was published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 11, 10, 10, 9, 4, '{"compensation": "3% is of the commissionable fare rather than the full booking value, but fares and order values are large.", "contact_access": "The program manager''s email is published and the brand runs a detailed affiliate FAQ.", "credibility": "Online cruise agency operating since 2001 under International Voyager Inc.", "niche_fit": "Cruise booking is a distinct, high-value travel niche.", "opportunity_availability": "No traffic minimums and 24-hour application review make this unusually accessible.", "ugc_evidence": "Affiliate route is well documented on the brand''s own site, though not creator-specific."}'::jsonb);
