  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/snap-supplements/', 'affiliate_network', 'affiliate', 'Lasso''s program directory lists Snap Supplements'' affiliate program on ShareASale at 16% commission per sale with a 14-day cookie and a $50 payout threshold.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ecrm.marketgate.com/Blog/2026/11/Scaling-Your-Brand-with-TikTok-Founders-Innovation-Day-CPG-Panel-Insights', 'listing', 'ugc_collab', 'ECRM''s Founders'' Innovation Day panel write-up quotes co-founder Alex Lomov: Snap generated over $50 million in sales on TikTok Shop by mobilizing an army of creator affiliates publishing thousands of videos every month, and remains a top-10 (often top-5) supplement seller on the platform.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://recruiting.paylocity.com/Recruiting/Jobs/Details/4602554?utm_id=18437736&utm_source=Digital+Marketing+Jobs', 'listing', 'ugc_collab', 'Snap Supplements'' own job posting for a TikTok Shop Affiliate Coordinator (Vancouver, WA) describes recruiting, developing and managing a portfolio of top-performing TikTok Shop creators, including samples, commissions and deliverables — evidence of a large, staffed creator affiliate operation.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 20, 13, 9, 9, 4, '{"niche_fit": "Supplements built for TikTok Shop creator selling \u2014 prostate, nitric oxide and hormone formulas are exactly the demo-driven products wellness creators post about.", "ugc_evidence": "The strongest UGC evidence in this batch: the co-founder publicly credits thousands of creator affiliate videos a month and $50M+ in TikTok Shop sales, and the brand employs dedicated TikTok Shop affiliate coordinators.", "compensation": "A published 16% per-sale rate on ShareASale per the network directory; TikTok Shop rates are set per product and not published on a fetched page.", "contact_access": "No public program email or application page was found on a fetched page; joining runs through ShareASale or TikTok Shop, so contact access is mid-band.", "opportunity_availability": "Open on two fronts \u2014 the ShareASale program and TikTok Shop''s open affiliate marketplace, where the brand actively recruits creators.", "credibility": "Eight-year-old brand, top-10 TikTok Shop supplement seller expanding into major retail chains, per trade-press coverage."}'::jsonb);
