  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 15, 11, 9, 4, '{"niche_fit": "Clean-label protein bars sit squarely in the healthy-snack content niche \u2014 gym bags, desk snacks and vegan haul videos.", "ugc_evidence": "The Awin profile runs explicit creator gifting campaigns and supplies lifestyle images, product shots and swipe copy to creators.", "compensation": "A single, clearly published rate \u2014 20% on every sale \u2014 stated on the network''s own merchant profile, with no conflicting figure found.", "contact_access": "Public Awin application route with dedicated program support promised in the profile; no direct program email published.", "opportunity_availability": "Applications are open on Awin and creators/influencers are an explicitly allowed publisher type.", "credibility": "20+ year-old brand with national distribution and a long retail track record."}'::jsonb);
