  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 8, 12, 9, 4, '{"niche_fit": "A creator-founded food brand whose protein shakes are sold primarily through short-form grocery and recipe content \u2014 a near-perfect UGC fit.", "ugc_evidence": "The brand runs a formal open affiliate program for TikTok Shop creators with published creator terms and advertising guidelines on its own site.", "compensation": "Commission is real and paid through TikTok Shop, but the brand publishes no rate in its terms (rates are set per product in TikTok Shop), so no figure is recorded.", "contact_access": "A published partnerships email on the brand''s own FAQ page plus the open TikTok Shop route.", "opportunity_availability": "An explicitly ''Open'' affiliate program \u2014 any TikTok Shop creator can add products and start earning.", "credibility": "Large, established creator-led brand with national grocery distribution."}'::jsonb);
