  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/lety85739/posts/pfbid0ak2qXkQAwe3aAis646NrKTTDm2G1mAqerz5EutCxnEX3m59TDatAt4XyWE2mY1y8l', 'listing', 'compensation', 'A screenshot of Primal Queen''s own welcome email to a new Affiliate Brand Ambassador shows a personal discount link giving followers 10% off and paying the ambassador a flat $15 per first purchase, with SEO/paid ads prohibited.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/reel/548820128073583/', 'listing', 'compensation', 'A December 2024 creator recruiting video describes a much richer offer — 100% commission on first-time orders and 25% for life on recurring orders, free starter kit, 1,000-follower minimum — which conflicts with the flat $15 first-purchase figure in the brand''s 2026 welcome email, so no rate is recorded.', 'needs_review', now());
