  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 18, 5, 10, 9, 4, '{"niche_fit": "A supplement formulated specifically for women, sold almost entirely through female creator testimonials \u2014 a strong women''s-wellness UGC fit.", "ugc_evidence": "A standing ambassador program with personal links, brand assets, starter kits and constant creator onboarding visible across social platforms.", "compensation": "Pay exists but the two documented figures conflict \u2014 a flat $15 per first purchase in the brand''s welcome email vs a 100% first-order claim in a 2024 recruiting video \u2014 so no rate is recorded and compensation scores low.", "contact_access": "A public join page on the brand''s own site; no program email published on a fetched page.", "opportunity_availability": "Applications are publicly open via the join page; a 1,000-follower minimum was reported in recruiting material.", "credibility": "Bootstrapped brand reporting $300M lifetime sales in under 30 months and a 900-store Target launch, per trade coverage."}'::jsonb);
