  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 5, 11, 8, 5, '{"niche_fit": "A wellness publisher selling its own supplements \u2014 its entire business is expert and creator content, so affiliate products slot straight into that content.", "ugc_evidence": "A named ambassador program (#mbgambassador) with community events, free-product milestones, and roughly two-thirds of its TikTok Shop sales attributed to affiliate creators.", "compensation": "The brand''s own page publishes 20% on supplements, but a network directory lists 5% \u2014 the conflict means no rate is recorded and compensation scores low.", "contact_access": "A public application form on the brand''s own shop domain; no program email published.", "opportunity_availability": "Applications are publicly open to wellness experts, providers and influencers via a short intake form.", "credibility": "One of the largest US wellness media brands, operating since 2009 with GMP-certified US manufacturing."}'::jsonb);
