  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 5, 11, 7, 4, '{"niche_fit": "Pre-workout, protein and energy drinks from a five-time Mr. Olympia''s brand \u2014 core fitness-creator products with a built-in athlete story.", "ugc_evidence": "A structured ambassador team (Team Thavage) with personal codes, a member portal and tier progression, documented in the brand''s own onboarding emails.", "compensation": "Sources conflict sharply \u2014 15% (Lasso), 2% (Shopper) and creator-reported 5/8/10% tiers \u2014 so no rate is recorded and compensation scores low.", "contact_access": "A published program team email, teamthavage@getrawnutrition.com, from the brand''s own onboarding email.", "opportunity_availability": "The ambassador team recruits publicly through the brand''s social channels, though no open application page was found on a fetched page.", "credibility": "One of the fastest-growing US supplement brands with national retail distribution and a celebrity-athlete co-founder."}'::jsonb);
