  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 6, 10, 7, 5, '{"niche_fit": "Clean longevity and performance supplements are a staple of the biohacking and fitness-creator niche Kion was built in.", "ugc_evidence": "The brand recruits affiliates through dedicated landing pages and influencer campaigns run on Aspire, though it publishes little public program detail.", "compensation": "A real program exists, but Kion publishes no rate or terms on its public pages, so nothing is recorded and compensation scores low.", "contact_access": "A public affiliate landing page on the brand''s own domain; the contact email on the page is obfuscated, so no email is recorded.", "opportunity_availability": "Affiliate recruitment is live via the brand''s landing page and Aspire campaigns, but application is campaign-based rather than a standing open form.", "credibility": "Established premium supplement brand with third-party testing, NSF-certified cGMP facilities and a well-known founder."}'::jsonb);
