  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 5, 8, 8, 3, '{"niche_fit": "Flavored collagen and women''s wellness supplements are heavily promoted through short-form creator content, Obvi''s home turf.", "ugc_evidence": "The brand publicly runs two affiliate tracks \u2014 customers and creators \u2014 with per-creator codes and links, and recruits ambassadors on its own Instagram.", "compensation": "Published figures conflict across the brand''s own materials (25% on Instagram, 30%/50% tiers in its playbook, 10% on Shopper), so no rate is recorded.", "contact_access": "No public program email or application page was found on a fetched page; entry is via the brand''s social recruiting and Social Snowball.", "opportunity_availability": "Recruiting is public and ongoing on the brand''s own channels, aimed at smaller creators as well as large influencers.", "credibility": "Established DTC collagen brand, though its aggressive recruiting attracts mixed public sentiment."}'::jsonb);
