  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 5, 12, 7, 4, '{"niche_fit": "Nootropics and focus supplements are a dedicated creator niche (biohacking, study and productivity content) that Natural Stacks helped define.", "ugc_evidence": "A long-running affiliate program with a dedicated affiliate manager and custom creative support, though it is publisher/blog-led more than short-form-creator-led.", "compensation": "Every source disagrees \u2014 15%, 20%, 25% and up to 30% all appear \u2014 so no rate is recorded and compensation scores low.", "contact_access": "A published program email, affiliate@naturalstacks.com, plus an application page on the brand''s official site.", "opportunity_availability": "Applications are open via the official affiliate page; some listings report a 5,000-follower/subscriber eligibility bar.", "credibility": "Operating since 2013 with a distinctive open-source-label reputation in the nootropics category."}'::jsonb);
