  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 6, 11, 8, 3, '{"niche_fit": "Vegan protein and superfoods fit the plant-based fitness niche well, though the brand is Canada-first and smaller than US rivals.", "ugc_evidence": "An open affiliate page explicitly recruiting influencers with tracking, banners and consumer gift incentives, but little public creator-program detail beyond that.", "compensation": "The brand confirms a tiered commission structure but publishes no numbers, so no rate is recorded.", "contact_access": "A public affiliate page with signup on the brand''s own domain; no program email published.", "opportunity_availability": "Applications are publicly open to Canada/US creators with a health, fitness or vegan audience.", "credibility": "Operating since 2017 with a clear niche identity, but modest scale and visibility outside Canada."}'::jsonb);
