  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wolfbox.com/pages/affiliate-program', 'official_site', 'affiliate', 'WOLFBOX''s own affiliate page invites review sites, online communities, bloggers and content creators to join free of charge, advertises ''up to 12%'' commission per successful referral, a 30-day cookie, and payouts through impact.com once the balance reaches $10. Because 12% is published only as a ceiling (''up to''), no single base rate is recorded.', 'verified', now());
