  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 12, 13, 8, 4, '{"compensation": "A commission ceiling of up to 12% is published on the brand''s own page, but no base rate is stated, so the recorded rate stays null and compensation scores mid-range.", "contact_access": "A dedicated affiliate email (affiliate@wolfbox.com) is published on the program page for questions and eligibility.", "credibility": "Established DTC gear brand with a detailed, transparent program page (cookie, payout threshold and prohibited methods all published).", "niche_fit": "Vehicle tech and off-road gear is a proven review and demo niche for tech creators, and the program is pitched directly at review sites and creators.", "opportunity_availability": "Open, free signup through the program page and Impact; no follower minimum is stated.", "ugc_evidence": "The brand''s own program page recruits content creators and bloggers by name, but no creator counts or campaign examples are published."}'::jsonb);
