  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/lefant-us', 'listing', 'affiliate', 'Rateful''s TikTok Shop analysis (30 days to Nov 3, 2026) reports about 70% of Lefant US''s estimated TikTok Shop sales came through affiliate creators'' videos and LIVEs, and that creators with TikTok Shop affiliate access can add Lefant products to their showcase and earn commission on every sale — the brand qualifies through its TikTok Shop affiliate program. No commission rate is published there, so the rate is null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/lefant/', 'affiliate_network', 'compensation', 'Lasso lists a Lefant affiliate offer of up to 7.5% per sale, but that route runs through Amazon marketplace sales rather than a brand-run program and does not publish the TikTok Shop rate, so no rate is recorded.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 10, 6, 9, 3, '{"compensation": "Commission exists on every affiliate sale but the rate is set per product inside TikTok Shop and is not published, so the recorded rate is null.", "contact_access": "No brand email or partnership page was found; the only route is inside TikTok Shop''s affiliate center.", "credibility": "Sales figures are third-party Rateful estimates rather than brand-published data, so credibility is held down.", "niche_fit": "Robot vacuums are a top demo-driven home-tech category on TikTok, and Lefant''s pet-hair positioning fits creator content well.", "opportunity_availability": "Open collaboration \u2014 any creator with TikTok Shop affiliate access can add the products and start posting.", "ugc_evidence": "About 70% of the brand''s TikTok Shop sales are reported to flow through affiliate creators \u2014 unusually strong, quantified creator evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Greenworks', 'https://www.greenworkstools.com', 'Leader in battery-powered outdoor power tools for DIY consumers, selling 24V to 82V cordless mowers, blowers, trimmers, chainsaws and snowblowers (100+ tools) through its own website and retail.', 'United States', 'published') returning id into bid;
