  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.greenworkstools.com/pages/affiliates.', 'https://www.greenworkstools.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Greenworks Affiliate Program (via Impact)', 'https://www.greenworkstools.com/pages/affiliates', 'https://www.greenworkstools.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.greenworkstools.com/pages/affiliates', 'official_site', 'affiliate', 'Greenworks'' own affiliates page says joining is free, commission runs 3%–6% across tiers that depend on the publisher''s promotional model, the cookie window is 30 days and typical AOV is $330+; the signup link points to app.impact.com. Because the published figure is a tier range with the exact rate assigned privately after application, no single rate is recorded.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.greenworkstools.com/pages/affiliates', 'official_site', 'compensation', 'The same page inconsistently states that payouts are handled through the Rakuten network and that creative assets sit in a Rakuten portal, while its signup link goes to Impact — a self-contradicting source. The network is recorded as Impact (the actual application route) and the contradiction is flagged here; no cap statement appears, so commission_cap is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 8, 8, 5, '{"compensation": "Published tiers of 3%\u20136% are low and the exact rate is only assigned privately after applying, so the recorded rate is null.", "contact_access": "Application runs through the brand''s own affiliates page into Impact; no direct affiliate email is published.", "credibility": "Major established tool brand with a detailed first-party FAQ; held back only by the page''s internal Rakuten/Impact inconsistency, which is documented in the evidence.", "niche_fit": "Outdoor power tools and yard gear are a solid home/garden creator niche, though less native to short-form UGC than indoor home tech.", "opportunity_availability": "Free, open publisher signup with no stated follower minimum.", "ugc_evidence": "The program recruits publishers and promoters with creative assets and seasonal campaigns, but publishes no creator-specific program or counts."}'::jsonb);
