  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kleankanteen.com/pages/affiliate-program', 'official_site', 'affiliate', 'Klean Kanteen''s own affiliate page publishes a 10% commission on every referred sale with higher percentage tiers as affiliates sell more, a 30-day cookie and a $50 average order value; applications run through AvantLink. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
